class TestCrossReferenceConsistency:
    """Validate consistency between constants and mappings."""

    def test_relations_reference_template_placeholders(self):
        """RELATIONS values must reference placeholders in templates."""
        t = DiagramTemplates()
        all_templates = " ".join([
            t.SEQUENCE, t.FLOWCHART, t.ERD, t.STATE, t.CLASS
        ])
        for key, value in t.RELATIONS.items():
            # Extract placeholder names from value
            placeholders = re.findall(r"\{(\w+)\}", value)
            for ph in placeholders:
                assert "{" + ph + "}" in all_templates, (
                    f"Placeholder {{{ph}}} in RELATIONS[{key}] not found in templates"
                )

    def test_relations_keys_match_template_sections(self):
        """RELATIONS keys should correspond to template sections."""
        t = DiagramTemplates()
        for key in t.RELATIONS.keys():
            # Key should appear in at least one template
            found = False
            for template in [t.SEQUENCE, t.FLOWCHART, t.ERD, t.STATE, t.CLASS]:
                if key.lower() in template.lower():
                    found = True
                    break
            assert found, f"Key {key} not found in any template"

    def test_template_placeholders_have_relations(self):
        """All placeholders in templates should have corresponding relations."""
        t = DiagramTemplates()
        all_templates = " ".join([
            t.SEQUENCE, t.FLOWCHART, t.ERD, t.STATE, t.CLASS
        ])
        template_placeholders = set(re.findall(r"\{(\w+)\}", all_templates))
        relation_placeholders = set()
        for value in t.RELATIONS.values():
            relation_placeholders.update(re.findall(r"\{(\w+)\}", value))
        
        # Placeholders in templates should be covered by relations
        uncovered = template_placeholders - relation_placeholders
        assert not uncovered, f"Uncovered placeholders: {uncovered}"


