class TestIntegration:
    """Validate integration with common usage patterns."""

    def test_format_sequence_template(self):
        """Should be able to format sequence template."""
        t = DiagramTemplates()
        result = t.SEQUENCE.format(
            participants="Alice\nBob",
            messages="Alice->>Bob: Hello"
        )
        assert "sequenceDiagram" in result
        assert "Alice" in result
        assert "Bob" in result

    def test_format_flowchart_template(self):
        """Should be able to format flowchart template."""
        t = DiagramTemplates()
        result = t.FLOWCHART.format(
            nodes="A[Start]\nB[End]",
            edges="A-->B"
        )
        assert "flowchart" in result or "graph" in result
        assert "A" in result
        assert "B" in result

    def test_format_erd_template(self):
        """Should be able to format ERD template."""
        t = DiagramTemplates()
        result = t.ERD.format(
            entities="CUSTOMER {\n  string name\n}",
            relations="CUSTOMER ||--o{ ORDER : places"
        )
        assert "erDiagram" in result
        assert "CUSTOMER" in result
        assert "ORDER" in result

    def test_format_state_template(self):
        """Should be able to format state template."""
        t = DiagramTemplates()
        result = t.STATE.format(
            states="[*] --> Idle\nIdle --> Working",
            transitions="Working --> [*]"
        )
        assert "stateDiagram" in result
        assert "Idle" in result
        assert "Working" in result

    def test_format_class_template(self):
        """Should be able to format class template."""
        t = DiagramTemplates()
        result = t.CLASS.format(
            classes="class Animal {\n  +String name\n}",
            relations="Animal <|-- Dog"
        )
        assert "classDiagram" in result
        assert "Animal" in result
        assert "Dog" in result

    def test_relations_usage_in_erd(self):
        """RELATIONS should be usable in ERD context."""
        t = DiagramTemplates()
        for key, value in t.RELATIONS.items():
            erd_context = f"erDiagram\nENTITY1 {value} ENTITY2"
            assert "erDiagram" in erd_context
            assert "ENTITY1" in erd_context
            assert "ENTITY2" in erd_context


